local now = 0
local timeoutQueue

local conf = {
  time = os.clock,
  setTimeout = function (f, delay)
    if not timeoutQueue then
      timeoutQueue = _G.System.TimeoutQueue()
    end
    return timeoutQueue:Add(now, delay, f)
  end,
  clearTimeout = function (t)
    timeoutQueue:Erase(t)
  end
}

func(conf)


function runTimeOut()
if timeoutQueue then
  while true do
    local nextExpiration = timeoutQueue:getNextExpiration()
    if nextExpiration ~= timeoutQueue.MaxExpiration then
      now = nextExpiration
      timeoutQueue:RunLoop(now)
      task.wait()
    else
      break
    end
  end
end
end

-- 有时候会生成 System.System,没来的及修，先补救一下

_G.System.System = _G.System

-- 热重载后,要暂停当前循环
_G.IsC2LRunning = true

task.spawn(
function()
  while _G.IsC2LRunning  do
    task.wait()
    runTimeOut()
  end
end
)


return {i=1}
